-- Additive migration for DREAMOPS v5. Does not alter earlier tables.
-- Run in Supabase SQL Editor. Uses invited Supabase Auth users only.
create table if not exists public.dreamops_members (
  user_id uuid primary key references auth.users(id) on delete cascade
);
alter table public.dreamops_members enable row level security;
drop policy if exists "Members see own membership" on public.dreamops_members;
create policy "Members see own membership" on public.dreamops_members
  for select to authenticated using (user_id=auth.uid());
grant select on public.dreamops_members to authenticated;

create table if not exists public.dreamops_workspace (
  id integer primary key check(id=1),
  data jsonb not null check(data->>'version'='5' and jsonb_typeof(data->'devices')='array'
    and jsonb_typeof(data->'orders')='array' and jsonb_typeof(data->'supplies')='array'
    and jsonb_typeof(data->'models')='array' and jsonb_typeof(data->'purchases')='array'
    and jsonb_typeof(data->'activity')='array'),
  revision bigint not null default 0,
  updated_at timestamptz not null default now()
);
alter table public.dreamops_workspace enable row level security;
drop policy if exists "Team reads workspace" on public.dreamops_workspace;
drop policy if exists "Team updates workspace" on public.dreamops_workspace;
create policy "Team reads workspace" on public.dreamops_workspace for select to authenticated
  using (exists(select 1 from public.dreamops_members where user_id=auth.uid()));
create policy "Team updates workspace" on public.dreamops_workspace for update to authenticated
  using (exists(select 1 from public.dreamops_members where user_id=auth.uid()))
  with check (exists(select 1 from public.dreamops_members where user_id=auth.uid()));
grant select,update on public.dreamops_workspace to authenticated;

-- Compare-and-swap in one PostgreSQL statement prevents concurrent lost updates.
create or replace function public.save_dreamops_workspace(expected_revision bigint,new_data jsonb)
returns bigint language plpgsql security invoker set search_path=public as $$
declare next_revision bigint;
begin
  update public.dreamops_workspace
     set data=new_data,revision=revision+1,updated_at=now()
   where id=1 and revision=expected_revision
   returning revision into next_revision;
  return next_revision;
end;
$$;
revoke all on function public.save_dreamops_workspace(bigint,jsonb) from public;
grant execute on function public.save_dreamops_workspace(bigint,jsonb) to authenticated;

